INSERT INTO collection_items (product_id, is_owned, date_acquired, store, seller, price_paid, shipping_cost, tax, notes, is_complete) VALUES (115, 1, '2026-08-11', 'eBay', 'elainasthriftedfinds', 10.5, NULL, NULL, 'Clear crackle glass with red hibiscus flowers and green leaves. Tropical theme. eBay listing described condition as used with some paint chipping; material glass, 1lb 8.5oz combined weight for the shade+plate set. No official Yankee Candle pattern name, MPN, or UPC given on the listing -- "Red Hibiscus" remains an unofficial working name. Listing sold for $24.99 total (shade+plate combined) on 8/11/26 -- the $15.75/$10.50 split recorded here doesn''t add up to that (totals $26.25); flagging in case the split needs correcting.', 0);
